func (this *Bitfinex) HandleOHLCV(client any, message []any, subscription map[string]any) {
	//
	// initial snapshot
	//   [
	//       341527, // channel id
	//       [
	//          [
	//             1654705860000, // timestamp
	//             1802.6, // open
	//             1800.3, // close
	//             1802.8, // high
	//             1800.3, // low
	//             86.49588236 // volume
	//          ],
	//          [
	//             1654705800000,
	//             1803.6,
	//             1802.6,
	//             1804.9,
	//             1802.3,
	//             74.6348086
	//          ],
	//          [
	//             1654705740000,
	//             1802.5,
	//             1803.2,
	//             1804.4,
	//             1802.4,
	//             23.61801085
	//          ]
	//       ]
	//   ]
	//
	// update
	//   [
	//       211171,
	//       [
	//          1654705680000,
	//          1801,
	//          1802.4,
	//          1802.9,
	//          1800.4,
	//          23.91911091
	//       ]
	//   ]
	//
	var data any = this.SafeList(message, 1, []any{})
	var ohlcvs any = []any{}
	var first []any = ccxt.SafeListTyped(data, 0)
	if first != nil {
		// snapshot
		ohlcvs = data
	} else {
		// update
		ohlcvs = []any{data}
	}
	var channel *string = this.SafeString(subscription, "channel", "")
	var key *string = this.SafeString(subscription, "key", "")
	var keyParts []string = strings.Split(*key, ":")
	var interval *string = this.SafeString(keyParts, 1, "")
	var marketId *string = this.SafeString(keyParts, 2, "")
	var market map[string]any = this.SafeMarket(marketId)
	var timeframe *string = this.FindTimeframe(interval)
	var symbol *string = ccxt.SafeStringPtr(market["symbol"])
	var messageHash string = *channel + ":" + *interval + ":" + *marketId
	if symbol != nil {
		if this.Ohlcvs[*symbol] == nil {
			this.Ohlcvs[*symbol] = map[string]any{}
		}
	}
	var stored any
	if symbol != nil {
		if timeframe != nil {
			stored = this.Ohlcvs[*symbol][*timeframe]
		}
	}
	if stored == nil {
		var limit *int64 = this.SafeInteger(this.Options, "OHLCVLimit", 1000)
		stored = ccxt.NewArrayCacheByTimestamp(limit)
		if symbol != nil && timeframe != nil && this.Ohlcvs[*symbol] != nil {
			this.Ohlcvs[*symbol][*timeframe] = stored
		}
	}
	var ohlcvsLength int = ccxt.GetArrayLength(ohlcvs)
	for i := 0; i < ohlcvsLength; i++ {
		var parsed any = ccxt.OHLCVToList(this.ParseOHLCV(this.SafeList(ohlcvs, (ohlcvsLength-i)-1), market))
		stored.(ccxt.Appender).Append(parsed)
	}
	client.(ccxt.ClientInterface).Resolve(stored, messageHash)
}

